/**
 *
 * DataTableCell is a component that displays a cell inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableCell
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableCell component.
 */
export type DataTableCellPassThroughType<E> = PassThroughType<DataTableCellInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableCell component.
 */
export interface DataTableCellPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableCellPassThroughType<React.HTMLAttributes<HTMLTableCellElement>>;
}
/**
 * Defines valid properties in DataTableCell component.
 */
export interface DataTableCellProps extends BaseComponentProps<DataTableCellInstance, unknown, DataTableCellPassThrough, 'td'> {
    /**
     * Number of columns a cell should span.
     * @default undefined
     */
    colSpan?: number | undefined;
    /**
     * Number of rows a cell should span. Used for rowspan-style row grouping.
     * @default undefined
     */
    rowSpan?: number | undefined;
    /**
     * Whether the column is frozen.
     * @default false
     */
    frozen?: boolean | undefined;
    /**
     * Position of the frozen column, valid values are "left" and "right".
     * @default 'left'
     */
    alignFrozen?: 'left' | 'right' | undefined;
}
/**
 * Defines valid state in DataTableCell component.
 */
export interface DataTableCellState {
    /**
     * Whether the column is frozen.
     */
    frozen: boolean | undefined;
}
/**
 * Defines the methods and properties exposed by DataTableCell component.
 */
export interface DataTableCellExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableCell component.
 */
export type DataTableCellInstance = ComponentInstance<DataTableCellProps, DataTableCellState, DataTableCellExposes>;
